let stormClock=48;
function updateUI(){el('gold').textContent=state.gold;el('wood').textContent=state.wood;el('rep').textContent=state.renown;el('hull-bar').style.width=state.hull+'%';el('hull-text').textContent=Math.round(state.hull)+'%';el('sail-bar').style.width=state.sails+'%';el('sail-text').textContent=Math.round(state.sails)+'%';el('ammo-count').textContent=state.ammo;el('ammo-dots').querySelectorAll('i').forEach((d,i)=>d.classList.toggle('empty',i>=state.ammo));el('speed-number').textContent=state.speed.toFixed(1);el('speed-gauge').style.width=Math.min(state.speed/8*100,100)+'%';el('ship-type').textContent=state.hullType.toUpperCase()+' · LVL 2';el('weapon-label').innerHTML=state.weapon.toUpperCase()+`<small>${state.weapon==='Torpedoes'?'DEEP RUNNER · FORWARD':'LONG NINE · BROADSIDE'}</small>`;el('guns-value').textContent=state.weapon==='Ballista'?2:state.weapon==='Torpedoes'?3:6;el('armor-value').textContent=state.hullType==='Galleon'?68:state.hullType==='Sloop'?30:42;el('speed-value').textContent=state.hullType==='Sloop'?88:state.hullType==='Galleon'?52:74;el('quest-progress').textContent=state.quest?'◉  Return to any port':'◉  Sink the Royal patrol';el('quest-count').textContent=state.quest?'1 / 1':'0 / 1';}
function showModal(html){el('modal').innerHTML=html;el('modal-backdrop').classList.remove('hidden');state.paused=true;}
function closeModal(){el('modal-backdrop').classList.add('hidden');state.paused=false;}
function customize(){
 showModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">SHIPYARD · PORT ROYAL</div><h2>Refit your vessel</h2><p class="subcopy">A captain's ship is never truly finished. Pick a hull and armament to match your next voyage.</p><div class="eyebrow" style="margin-top:16px">HULL CLASS</div><div class="modal-options" id="hull-options"><button class="option ${state.hullType==='Sloop'?'selected':''}" data-hull="Sloop"><b>Swift Sloop</b><small>Fast, nimble · light armor</small><em>180g</em></button><button class="option ${state.hullType==='Brigantine'?'selected':''}" data-hull="Brigantine"><b>Brigantine</b><small>Balanced · two masts</small><em>—</em></button><button class="option ${state.hullType==='Galleon'?'selected':''}" data-hull="Galleon"><b>War Galleon</b><small>Heavy guns · reinforced hull</small><em>320g</em></button><button class="option ${state.weapon==='Ballista'?'selected':''}" data-weapon="Ballista"><b>Deck Ballista</b><small>Armor-piercing bolt · long range</small><em>110g</em></button><button class="option ${state.weapon==='Torpedoes'?'selected':''}" data-weapon="Torpedoes"><b>Sea Torpedoes</b><small>Experimental · forward launch</small><em>160g</em></button><button class="option ${state.weapon==='Iron Cannons'?'selected':''}" data-weapon="Iron Cannons"><b>Iron Cannons</b><small>Broadside · dependable</small><em>—</em></button></div><div class="modal-footer"><span>GOLD <b style="color:#e4c477">${state.gold}</b></span><button class="primary-btn" id="apply-refit">APPLY REFIT ↗</button></div>`);
 let selectedHull=state.hullType,selectedWeapon=state.weapon;
 el('modal').querySelectorAll('[data-hull]').forEach(b=>b.onclick=()=>{selectedHull=b.dataset.hull;el('modal').querySelectorAll('[data-hull]').forEach(x=>x.classList.toggle('selected',x===b))});
 el('modal').querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>{selectedWeapon=b.dataset.weapon;el('modal').querySelectorAll('[data-weapon]').forEach(x=>x.classList.toggle('selected',x===b))});
 el('apply-refit').onclick=()=>{const cost=(selectedHull==='Sloop'?180:selectedHull==='Galleon'?320:0)+(selectedWeapon==='Ballista'?110:selectedWeapon==='Torpedoes'?160:0);if(cost>state.gold){toast('Not enough gold for that refit.');return}if(selectedHull!==state.hullType&&selectedHull!=='Brigantine'){state.gold-=selectedHull==='Sloop'?180:320;world.remove(player);const fresh=makeShip({type:selectedHull==='Sloop'?'sloop':'brigantine'});fresh.position.copy(player.position);fresh.rotation.y=player.rotation.y;player.clear();player.add(...fresh.children);player.userData=fresh.userData;state.hull=100;state.hullType=selectedHull}else if(selectedHull==='Brigantine'&&state.hullType!=='Brigantine'){toast('Hull change available at a shipyard.');return}if(selectedWeapon!==state.weapon&&selectedWeapon!=='Iron Cannons'){state.gold-=selectedWeapon==='Ballista'?110:160}state.weapon=selectedWeapon;updateUI();closeModal();toast('Refit complete. Fair winds, Captain.');log('Your vessel has been refitted.');};
}
function openPort(island){portOpen=true;const port=island.userData.name;el('region-label').textContent=port.toUpperCase();showModal(`<button class="modal-close" data-close>×</button><div class="eyebrow">FREE PORT · ${port.toUpperCase()}</div><h2>Safe harbor</h2><p class="subcopy">The quay is busy with merchants, shipwrights, and rumors from across the Reach. What do you need, Captain?</p><div class="faction-list"><span class="faction active">FREE CAPTAINS</span><span class="faction">ROYAL NAVY</span><span class="faction">ISLAND LEAGUE</span><span class="faction">CORSAIRS</span></div><div class="port-grid"><div class="trade-card"><h3>Buy provisions</h3><p>Timber repairs hull and keeps the ship seaworthy.<br>Current stock: ${state.wood} timber</p><button data-trade="wood">BUY 10 TIMBER · 40G</button></div><div class="trade-card"><h3>Sell cargo</h3><p>Trade timber to the island's shipwrights.<br>Receive 4 gold per timber.</p><button data-trade="sell">SELL 10 TIMBER · +40G</button></div><div class="trade-card"><h3>Repair hull</h3><p>Patch damage and restore the ship's integrity.</p><button data-trade="repair">REPAIR 25 HULL · 35G</button></div><div class="trade-card"><h3>Rumor &amp; bounty</h3><p>The Crown's patrols are closing in. Bring down a warship for a reward.</p><button data-trade="bounty">ACCEPT BOUNTY · +90G</button></div></div><div class="modal-footer"><span>HOLDINGS · ${state.gold} GOLD · ${state.wood} TIMBER</span><button class="primary-btn" data-close>CAST OFF</button></div>`);
 el('modal').querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>{const action=b.dataset.trade;if(action==='wood'){if(state.gold<40){toast('Not enough gold.');return}state.gold-=40;state.wood+=10;toast('Loaded 10 timber.')}if(action==='sell'){if(state.wood<10){toast('You need 10 timber to trade.');return}state.wood-=10;state.gold+=40;toast('Cargo sold for 40 gold.')}if(action==='repair'){if(state.gold<35){toast('Not enough gold.');return}state.gold-=35;state.hull=Math.min(100,state.hull+25);toast('Hull repaired.')}if(action==='bounty'){state.quest=true;state.gold+=90;state.renown+=3;toast('Bounty accepted: Royal ships are fair game.')}updateUI();closeModal();});
}
function fire(){if(state.paused||state.reload>0||state.ammo<=0)return;state.ammo--;state.reload=1.15;updateUI();const pos=player.position.clone();pos.y+=1.2;const dir=new THREE.Vector3(Math.cos(player.rotation.y),0,-Math.sin(player.rotation.y));let target=null,best=65;enemies.forEach(e=>{const d=pos.distanceTo(e.position);if(d<best){best=d;target=e}});const to=target?target.position.clone().add(new THREE.Vector3((Math.random()-.5)*3,1,(Math.random()-.5)*3)):pos.clone().add(dir.multiplyScalar(24));addShot(pos,to,'player');if(target&&best<55){target.userData.hull-=state.weapon==='Ballista'?34:state.weapon==='Torpedoes'?48:24;addBurst(target.position.clone().add(new THREE.Vector3(0,1,0)),0xffaa58);toast(`${target.userData.name} struck!`);if(target.userData.hull<=0)destroyEnemy(target)}else{toast('Broadside away!');}log(target&&best<55?'Broadside struck a hostile vessel.':'A broadside thunders across the sea.');}
function destroyEnemy(ship){addBurst(ship.position.clone().add(new THREE.Vector3(0,1,0)),0xff7b3b);world.remove(ship);enemies.splice(enemies.indexOf(ship),1);state.gold+=75;state.wood+=5;state.renown+=5;if(ship.userData.faction==='Royal Navy'||!state.quest){state.quest=true;el('quest-title').innerHTML='A Debt of<br>Black Powder';el('quest-copy').textContent='The Royal patrol is no more. Return to port to collect your reward and choose your next course.'}updateUI();toast('Enemy sunk · +75 gold, +5 timber');log('Enemy vessel sunk. Salvage recovered.');}
function interact(){if(state.nearPort){openPort(state.nearPort);return}toast('No port close enough. Sail toward the island marked on your horizon.');}
el('customize-btn').onclick=customize;el('sound-btn').onclick=()=>toast('Ambient sea sound is muted in this voyage.');el('modal').addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeModal()});
const keys={};addEventListener('keydown',e=>{const key=e.key.toLowerCase();keys[key]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key===' '&&!e.repeat)fire();if(key==='e'&&!e.repeat)interact();if(key==='escape'&&!el('modal-backdrop').classList.contains('hidden'))closeModal();if(key==='shift')state.fullSail=true});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key==='Shift')state.fullSail=false});

